const $ = (s, r=document) => r.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=[['#eef3de','#728c44'],['#e7f2e8','#4e8561'],['#f9eedd','#ae854b'],['#e8edf8','#697cb1'],['#f7e7e1','#ae725b'],['#eee9f5','#8a70a3'],['#e6eff1','#518591']];
let progress={mastered:[],visited:[],bookmarks:[],notes:{},last:'foundations'};
let storageAvailable=true;
try { const saved=JSON.parse(localStorage.getItem('odoo-functional-fieldnotes-v1')||'null'); if(saved && Array.isArray(saved.mastered)) progress={...progress,...saved}; } catch { storageAvailable=false; }
let quizState={}, labState={}, timer=null, toastTimer=null, currentTopic=null;
const validId=id=>topics.some(t=>t.id===id);
progress.mastered=progress.mastered.filter(validId);progress.visited=progress.visited.filter(validId);progress.bookmarks=progress.bookmarks.filter(validId);
function save(){try{localStorage.setItem('odoo-functional-fieldnotes-v1',JSON.stringify(progress))}catch{storageAvailable=false;toast('Browser storage is unavailable. Progress lasts for this session.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function xp(){return progress.mastered.length*30}
function percent(){return Math.round(progress.mastered.length/topics.length*100)}
function palette(i){return `--tint:${colors[i%colors.length][0]};--tone:${colors[i%colors.length][1]}`}
function heroArt(){return `<svg class="hero-art" role="img" aria-label="A friendly robot explores numbered blocks and a branching tree" viewBox="0 0 420 300"><defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".8" fill="#c1cfad"/></pattern><filter id="shade"><feDropShadow dx="0" dy="5" stdDeviation="5" flood-color="#5b7859" flood-opacity=".08"/></filter></defs><rect width="420" height="300" fill="url(#dots)"/><ellipse cx="222" cy="269" rx="133" ry="13" fill="#d8e5cc"/><path d="M64 133C67 83 116 85 126 59M284 145c68-6 88-40 65-66" fill="none" stroke="#8fa47b" stroke-width="1.5" stroke-dasharray="4 5"/><g transform="rotate(-7 77 149)" filter="url(#shade)"><rect x="24" y="129" width="116" height="66" rx="12" fill="#fffdf7" stroke="#d2dcc4"/><text x="37" y="145" fill="#99a688" font-family="monospace" font-size="8">ARRAY OF POSSIBILITIES</text><rect x="35" y="155" width="26" height="27" rx="5" fill="#deebbc" stroke="#9aaf71"/><rect x="68" y="155" width="26" height="27" rx="5" fill="#f2dab9" stroke="#cda36c"/><rect x="101" y="155" width="26" height="27" rx="5" fill="#deebbc" stroke="#9aaf71"/><g fill="#5a7050" font-family="monospace" font-size="12" text-anchor="middle"><text x="48" y="173">0</text><text x="81" y="173">1</text><text x="114" y="173">2</text></g></g><g transform="rotate(5 310 89)"><rect x="272" y="30" width="116" height="106" rx="13" fill="#fffdf7" stroke="#d2dcc4"/><path d="M330 60l-30 29m30-29 30 29m-60 0-14 25m14-25 14 25m46-25-14 25m14-25 14 25" fill="none" stroke="#9aad87" stroke-width="1.6"/><g fill="#e0edc1" stroke="#97ac77"><circle cx="330" cy="59" r="12"/><circle cx="300" cy="88" r="10"/><circle cx="360" cy="88" r="10"/><circle cx="286" cy="114" r="7"/><circle cx="314" cy="114" r="7"/><circle cx="346" cy="114" r="7"/><circle cx="374" cy="114" r="7"/></g><text x="330" y="63" text-anchor="middle" fill="#6b8556" font-size="10" font-family="monospace">8</text></g><g filter="url(#shade)"><path d="M194 214l-5 39m52-39 8 39" stroke="#55775c" stroke-width="11" stroke-linecap="round"/><path d="M185 253h-15m82 0h15" stroke="#365b47" stroke-width="12" stroke-linecap="round"/><rect x="181" y="177" width="74" height="52" rx="17" fill="#78a185" stroke="#39654b" stroke-width="2"/><rect x="201" y="190" width="34" height="24" rx="6" fill="#c6dca8"/><path d="M210 202h16m-8-8v16" stroke="#729357" stroke-width="2"/><path d="M181 188l-22 16m96-16 27-22" stroke="#668d70" stroke-width="10" stroke-linecap="round"/><circle cx="158" cy="205" r="7" fill="#9db894"/><circle cx="282" cy="163" r="7" fill="#9db894"/><path d="M219 105v-18" stroke="#55775c" stroke-width="3"/><circle cx="219" cy="83" r="6" fill="#e8b774"/><rect x="168" y="109" width="98" height="73" rx="25" fill="#b8d0a2" stroke="#547653" stroke-width="2"/><rect x="178" y="123" width="78" height="43" rx="15" fill="#f7f9e9"/><g fill="#375e46"><ellipse cx="198" cy="140" rx="4" ry="6"/><ellipse cx="236" cy="140" rx="4" ry="6"/></g><path d="M209 149q8 7 16 0" fill="none" stroke="#537252" stroke-width="2" stroke-linecap="round"/><ellipse cx="188" cy="151" rx="5" ry="2.5" fill="#ecc89b"/><ellipse cx="245" cy="151" rx="5" ry="2.5" fill="#ecc89b"/></g><rect x="90" y="31" width="130" height="33" rx="12" fill="#fffef6" stroke="#d8e2cc"/><path d="M157 63l9 10 2-10" fill="#fffef6" stroke="#d8e2cc"/><text x="155" y="52" text-anchor="middle" fill="#768a67" font-family="DM Sans,sans-serif" font-size="11">let’s figure it out together!</text><g fill="#c1d5a0"><path d="M68 70h11m-5-5v10" stroke="#a2b581" stroke-width="1.5"/><path d="M328 219h12m-6-6v12" stroke="#a2b581" stroke-width="1.5"/><circle cx="146" cy="242" r="3"/><circle cx="292" cy="42" r="2"/></g></svg>`}
function layout(content,view){let courseActive=['course','lesson'].includes(view);return `<div class="menu-scrim" id="menuScrim"></div><aside class="sidebar" id="sidebar"><a href="#home" class="brand"><span class="logo"><i></i><i></i><i></i><i></i></span><span>data playground<small>LEARN. PLAY. UNDERSTAND.</small></span></a><nav class="side-nav" aria-label="Main navigation"><a href="#home" class="${view==='home'?'active':''}"><span class="nav-icon">⌂</span>Overview</a><a href="#course" class="${courseActive?'active':''}"><span class="nav-icon">▤</span>Learning path<span style="margin-left:auto;font-size:10px;color:#8da077">${topics.length}</span></a><a href="#playground" class="${view==='playground'?'active':''}"><span class="nav-icon">◉</span>Playground</a><a href="#journey" class="${view==='journey'?'active':''}"><span class="nav-icon">⚑</span>My journey</a><a href="#cheatsheet" class="${view==='cheatsheet'?'active':''}"><span class="nav-icon">▧</span>Revision sheet</a></nav><div class="side-label">YOUR CHAPTERS</div><nav class="chapter-nav" aria-label="Chapters">${chapterInfo.map((c,i)=>`<a href="#course/${i}"><span style="color:${colors[i%colors.length][1]}">${c[2]}</span>${c[0]}<em>${topics.filter(t=>t.chapter===i).length}</em></a>`).join('')}</nav><div class="side-bottom"><div class="progress-card"><div class="row"><strong>A little better every day</strong><span style="font-size:10px">${percent()}%</span></div><div class="progress-track"><span style="width:${percent()}%"></span></div><div class="muted" style="font-size:10px">${progress.mastered.length} of ${topics.length} lessons completed</div></div><p class="side-note">Small steps. Big “aha!” moments.</p></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="mobile-menu" id="menuButton" aria-label="Open navigation" aria-expanded="false">☰</button><div class="breadcrumb">Your learning space <span>/</span> <strong>${({home:'Overview',course:'Learning path',lesson:currentTopic?.title,playground:'Playground',journey:'My journey',cheatsheet:'Revision sheet'})[view]}</strong></div></div><div class="top-actions"><button class="search-trigger" id="openSearch"><span>⌕ &nbsp; Find a topic</span><span class="key">⌘ K</span></button><span class="xp"><span>✦</span>${xp()} XP</span><span class="avatar" title="Your learning space">✿</span></div></header><main id="main" class="main" tabindex="-1">${content}<footer class="footer"><span>Made for curious minds. Go at your own pace.</span><span>${storageAvailable?'Progress saved in this browser':'Progress saved for this session'} · Original learning stories</span></footer></main></div>`}
function chapterCards(){return chapterInfo.map((c,i)=>{let ts=topics.filter(t=>t.chapter===i);let done=ts.filter(t=>progress.mastered.includes(t.id)).length;return `<a href="#course/${i}" class="path-card" style="${palette(i)}"><div class="row"><span class="chapter-icon">${c[2]}</span><span class="tiny-pill">${i===0?'Start here':i===6?'Go further':'Chapter '+String(i+1).padStart(2,'0')}</span></div><div class="chapter-number">${String(i+1).padStart(2,'0')} / ${i<2?'THE FOUNDATIONS':i<5?'BUILD YOUR SKILLS':'THINK LIKE A PROBLEM SOLVER'}</div><h3>${c[0]}</h3><p>${c[1]}</p><div class="card-bottom"><span>${ts.length} lessons · ${done ? done+' completed':'Explore at your pace'}</span><span>↗</span></div></a>`}).join('')}
function nextTopic(){return topics.find(t=>!progress.mastered.includes(t.id))||topics[0]}
function home(){let next=progress.visited.length?topics.find(t=>t.id===progress.last)||nextTopic():topics[0];return `<div class="welcome-row"><div><h2>A good day for a little discovery ☀</h2><p>Your next “aha!” moment is just a few clicks away.</p></div><span class="small-badge"><i class="dot"></i>Beginner friendly. Engineer ready.</span></div><section class="hero"><div><div class="eyebrow">Data structures & algorithms, made human</div><h1>Big ideas.<br><em>Little steps.</em></h1><p>Less memorizing. More understanding.<br>Explore DSA through everyday stories, playful experiments, and those lovely “I get it!” moments.</p><div class="hero-links"><a class="btn primary" href="#lesson/${next.id}">${progress.visited.length?'Continue learning':'Let’s start exploring'} <span>↗</span></a><a class="btn plain" href="#playground">Take a look around →</a></div><div class="hero-foot"><span>✓ No experience needed</span><span>✓ Learn by doing</span><span>✓ Your pace, always</span></div></div>${heroArt()}</section><div class="feature-strip"><div class="feature"><span class="feature-icon">✧</span><div><strong>Stories before syntax</strong><p>First a pancake. Then a stack.</p></div></div><div class="feature"><span class="feature-icon">⌘</span><div><strong>Make the ideas move</strong><p>Click, change, and watch what happens.</p></div></div><div class="feature"><span class="feature-icon">⚑</span><div><strong>Small wins that add up</strong><p>Friendly quizzes. Real understanding.</p></div></div></div><div class="section-head"><div><h2>Your adventure, chapter by chapter</h2><p>A path from “what is an array?” to “I can solve this.”</p></div><a class="text-link" href="#course">All ${topics.length} lessons →</a></div><section class="path-grid" aria-label="Learning chapters">${chapterCards()}</section><section class="bottom-banner"><div class="row"><span style="font-size:29px">☄</span><div><strong>Not sure where to begin? Start with a toy room.</strong><p>A 5-minute story that makes the whole DSA world feel smaller.</p></div></div><a class="btn warm" href="#lesson/foundations">Meet your first idea →</a></section>`}
function item(t,i){let mastered=progress.mastered.includes(t.id);return `<a class="lesson-item" href="#lesson/${t.id}"><span class="lesson-no">${mastered?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${t.title}</strong><p>${t.analogy}</p></span><span class="arrow">${progress.bookmarks.includes(t.id)?'★':'↗'}</span></a>`}
function course(){return `<div class="page-intro"><span class="eyebrow">The complete learning path</span><h1>One idea at a time.<br>A whole world of possibilities.</h1><p>${topics.length} original lessons across 7 chapters. Start from the beginning or follow your curiosity. Every topic is open.</p></div><label class="visually-hidden" for="courseFilter">Filter lessons</label><input id="courseFilter" class="filter-input" placeholder="Find a lesson in this path…"><div id="courseList">${chapterInfo.map((c,i)=>`<section class="chapter-section" id="chapter-${i}" style="${palette(i)}"><div class="chapter-heading"><span class="chapter-icon">${c[2]}</span><div><span class="eyebrow">Chapter ${String(i+1).padStart(2,'0')}</span><h2>${c[0]}</h2><p>${c[1]}</p></div></div><div class="lesson-list">${topics.filter(t=>t.chapter===i).map((t)=>item(t,topics.indexOf(t))).join('')}</div></section>`).join('')}</div>`}
function lesson(t){let i=topics.indexOf(t),marked=progress.bookmarks.includes(t.id);return `<div class="lesson-layout"><article class="lesson-content"><div class="lesson-top"><a class="text-link" href="#course/${t.chapter}">← ${chapterInfo[t.chapter][0]}</a><span class="small-badge">Lesson ${i+1} of ${topics.length}</span><button class="btn plain" id="bookmark">${marked?'★ Saved':'☆ Save lesson'}</button></div><div class="lesson-heading"><h1>${t.title}</h1><p>Let’s make this idea feel like something you already know.</p></div><section id="story" class="story-card"><span class="eyebrow">First, picture this</span><h2>${t.analogy}</h2><p>${t.story}</p></section><section class="lesson-section" id="idea"><h2><span class="section-num">01</span>The idea behind the story</h2><div class="concept">${t.meaning}</div><div class="steps">${t.steps.map((s,i)=>`<div class="step"><span>${i+1}</span>${s}</div>`).join('')}</div><div class="walkthrough"><button id="walkStep" class="btn">Walk me through →</button><p id="walkText" aria-live="polite">Take it one step at a time.</p></div></section><section class="lesson-section" id="experiment"><h2><span class="section-num">02</span>Make it click</h2><p class="muted">${labInfo(t).note} Change something and see what happens.</p>${labMarkup(t)}</section><section class="lesson-section" id="engineer"><h2><span class="section-num">03</span>Put your engineering hat on</h2><div class="engineering"><div class="eng-card"><h4>Where this earns its place</h4><p>${t.use}</p></div><div class="eng-card"><h4>Time & memory</h4><p>${t.cost}</p></div><div class="eng-card caution"><h4>Watch out for this little trap</h4><p>${t.trap}</p></div></div></section><section class="lesson-section" id="code"><h2><span class="section-num">04</span>From idea to Python</h2><p class="muted">A focused example of the central idea. Snippets with named graph/tree inputs are building blocks, not full programs.</p><div class="code-card"><div class="code-head"><span>PYTHON 3 · ${t.title.toUpperCase()}</span><button id="copyCode">Copy example ⧉</button></div><pre><code>${esc(t.code)}</code></pre></div></section><section class="lesson-section" id="check"><h2><span class="section-num">05</span>Your little “aha!” check</h2><p class="muted">Three checks. No timer, no pressure. Wrong answers come with a useful explanation.</p><div id="quiz">${quizMarkup(t)}</div></section><section class="lesson-section" id="practice"><h2><span class="section-num">06</span>Think it through</h2><div class="challenge"><p><strong>Be the teacher.</strong> Explain ${t.title.toLowerCase()} using this lesson’s everyday story. Then trace the example by hand and predict what changes if the input is empty, has a duplicate, or is much larger.</p><details><summary>A hint to get you started</summary><p style="margin-top:12px">Start with “${t.analogy}.” Walk through these three moves: ${t.steps.join(' ')} The key engineering caution is: ${t.trap}</p></details></div></section><section class="lesson-section"><h2><span class="section-num">07</span>Keep your own “aha!”</h2><label for="notes" class="muted">Your private notes · Saved in this browser</label><textarea id="notes" class="notes" placeholder="In my own words, this is like…">${esc(progress.notes[t.id]||'')}</textarea><p class="muted" id="noteStatus">Write it as if you’re explaining it to a younger friend.</p></section><div class="next-lesson">${i?`<a class="text-link" href="#lesson/${topics[i-1].id}">← Previous idea</a>`:'<span></span>'}${i<topics.length-1?`<a class="btn primary" href="#lesson/${topics[i+1].id}">Next: ${topics[i+1].title} →</a>`:'<a class="btn primary" href="#journey">Celebrate your journey →</a>'}</div></article><aside class="lesson-aside"><h4>YOUR LITTLE ROADMAP</h4><div class="progress-track"><span style="width:${progress.mastered.includes(t.id)?100:0}%"></span></div>${[['story','The story'],['idea','The idea'],['experiment','Try it yourself'],['engineer','Engineering lens'],['code','Python example'],['check','Knowledge check'],['practice','Think it through']].map(([id,name],i)=>`<a href="#lesson/${t.id}" data-scroll="${id}">${String(i+1).padStart(2,'0')} &nbsp; ${name}</a>`).join('')}<hr style="border:0;border-top:1px solid var(--line);margin:15px 0"><p class="muted" style="font-size:11px">Understanding beats speed.<br>Stay curious. Take a break.</p><button class="btn" id="focusToggle">Focus view ◉</button></aside></div>`}
const labQuestions={
array:['Start with [4,8,12,6]. Append 5. Where does 5 go?',['At the end','Before every item','Over index 0'],0,'Append adds a new item after the existing items.'],
linked:['After the final node of a singly linked chain, you reach…',['None','An automatic index lookup','The head, always'],0,'A normal singly linked list ends with a missing next reference.'],
stack:['After pushing 42 on a stack, an immediate pop removes…',['42','The oldest item','Every item'],0,'The last item pushed is the top item.'],
queue:['In the queue lab [4,8,12,6], the first dequeue removes…',['4','6','12'],0,'FIFO removes the front item, which arrived first.'],
hash:['With key mod 4, keys 4 and 8…',['Share bucket 0','Cannot both be stored','Are the same key'],0,'Both hash to bucket 0, but collision handling keeps them distinct.'],
tree:['In the BST lab, search for 6 follows…',['8 → 4 → 6','8 → 12 → 14','8 → 4 → 2'],0,'6 is below 8 but above 4, so search goes left then right.'],
heap:['In the min-heap lab, the first extracted priority is…',['2','9','7'],0,'The smallest key is at the root.'],
trie:['A terminal marker in the prefix lab means…',['A complete stored word ends here','No word has this prefix','The characters are sorted'],0,'A prefix path alone is not enough to identify a complete word.'],
range:['For [2,4,6,8,10,12], range [1,4) sums to…',['18','20','10'],0,'Indexes 1,2,3 contain 4,6,8; their sum is 18.'],
graph:['In the graph lab, A has direct neighbors…',['B and C','D and F','E only'],0,'The displayed edges connect A directly to B and C.'],
bfs:['BFS from A visits which layer before D and E?',['B and C','F only','No other vertex'],0,'B and C are one edge from A; D and E are farther.'],
dfs:['Why does the DFS lab avoid visiting a vertex twice?',['It tracks visited vertices','Every graph is a tree','It sorts all labels'],0,'Visited tracking prevents cycles from causing repeated exploration.'],
weighted:['In the weighted lab, A → B → D costs…',['3','7','5'],0,'A–B costs 2 and B–D costs 1, for a total of 3.'],
search:['In [4,8,12,6], linear search finds 8 after…',['Two checks','One check','Four checks necessarily'],0,'Check 4 first, then find 8 at index 1.'],
binary:['The binary-search lab can discard half because…',['The values are sorted','All values have equal length','It uses a hash bucket'],0,'Sorted order makes the midpoint comparison informative.'],
sort:['What must hold in the final ascending sorted row?',['Every value is no larger than the next','All values are equal','The biggest value comes first'],0,'Ascending order permits equality and puts smaller values first.'],
merge:['When merging two sorted rows, choose next…',['The smaller available front value','An arbitrary last value','The biggest value anywhere'],0,'Front values are each row’s minimum remaining values.'],
quick:['After a pivot partition, values smaller than the pivot go…',['To its left side','Only at the end','Outside the result'],0,'Partitioning separates smaller and larger keys around the pivot.'],
recursion:['In the factorial lab, factorial(1) returns…',['1','0','4'],0,'The base case factorial(1)=1 stops further recursion.'],
backtrack:['After recording [1,2,3], the lab undoes choices to…',['Explore other permutations','Lose all recorded answers','Change the original problem'],0,'Returning to an earlier partial choice allows a different branch.'],
greedy:['After accepting activity [1,3], [2,5] is…',['Skipped because it overlaps','Accepted because it is longer','Always optimal'],0,'It begins at 2, before the chosen activity finishes at 3.'],
dp:['In the Fibonacci lab, F(4)=3 and F(5)=5. F(6) is…',['8','15','2'],0,'The next state adds the previous two answers: 3+5=8.'],
pointers:['For sorted pair sum, if the sum is too large, move…',['The right pointer left','The left pointer right','Both pointers off the array'],0,'A smaller right-hand value can reduce the sum.'],
window:['Sliding [2,4,6] right to [4,6,8] changes the sum by…',['Subtract 2 and add 8','Add every value twice','Subtract 8 and add 2'],0,'The first item leaves and the next item enters.'],
bits:['Starting from 0, toggling bit 2 produces…',['4','2','8'],0,'Bit positions start at 0; bit 2 contributes 2²=4.'],
bigo:['If n doubles, the function n² becomes…',['Four times as large','Twice as large','Unchanged'],0,'(2n)²=4n², illustrating quadratic growth.'],
matrix:['In the row-major 3×3 lab, value 6 is at…',['row 1, column 2','row 2, column 1','row 0, column 6'],0,'Rows and columns are zero-indexed: the second row holds 4,5,6.']
};
function quizQuestions(t){
 const peers=topics.filter(p=>p.id!==t.id && p.chapter===t.chapter);
 const p1=peers[0]||topics[1],p2=peers[peers.length-1]||topics[2];
 const rotate=(arr,correct,offset)=>({answers:arr.slice(offset).concat(arr.slice(0,offset)),answer:(correct-offset+arr.length)%arr.length});
 const l=labQuestions[t.sim]||labQuestions.array;
 return [{question:t.question,answers:t.answers,answer:t.answer,reason:t.reason},
 {question:l[0],...rotate(l[1],l[2],(topics.indexOf(t)+1)%3),reason:l[3]},
 {question:`Which caution is emphasized in this lesson on ${t.title.toLowerCase()}?`,...rotate([t.trap,p1.trap,p2.trap],0,(topics.indexOf(t)+2)%3),reason:t.trap}];
}
function quizMarkup(t){let s=quizState[t.id]||(quizState[t.id]={index:0,selected:null,passed:[]});if(s.index===3){return `<div class="completion"><div style="font-size:32px">✦</div><span class="eyebrow">A new idea, understood</span><h3>You made it click!</h3><p>All three checks complete. ${progress.mastered.includes(t.id)?'This lesson is part of your learning journey.':''}</p><button class="btn" id="retryQuiz">Try the checks again ↺</button><a class="btn primary" href="#lesson/${nextTopic().id}">Explore the next idea →</a></div>`}let q=quizQuestions(t)[s.index],chosen=s.selected!==null,correct=s.selected===q.answer;return `<div class="quiz-card"><div class="quiz-progress">${[0,1,2].map(i=>`<span class="${s.passed.includes(i)?'filled':''}"></span>`).join('')}</div><span class="eyebrow">Check ${s.index+1} / 3</span><h3>${q.question}</h3><div class="options">${q.answers.map((a,i)=>`<button class="option ${chosen&&i===s.selected?(correct?'correct':'wrong'):''}" data-answer="${i}" ${chosen?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(a)}</span></button>`).join('')}</div>${chosen?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'That’s it!':'A useful wrong turn.'}</strong> ${correct?q.reason:'Think about this: '+q.reason}</div><button class="btn primary" id="quizNext">${correct?(s.index===2?'Finish this lesson ✦':'Next little check →'):'Give it another go ↺'}</button>`:'<p class="muted">Pick an answer. Your reasoning matters more than your first guess.</p>'}</div>`}
function bindQuiz(t){$('#quiz').onclick=e=>{let b=e.target.closest('[data-answer]');let s=quizState[t.id];if(b){s.selected=+b.dataset.answer;$('#quiz').innerHTML=quizMarkup(t)};if(e.target.closest('#quizNext')){let q=quizQuestions(t)[s.index];if(s.selected===q.answer){s.passed.push(s.index);s.index++;s.selected=null;if(s.index===3&&!progress.mastered.includes(t.id)){progress.mastered.push(t.id);save();toast('An idea understood. +30 XP ✦');$('.xp').innerHTML='<span>✦</span>'+xp()+' XP';$('.progress-card').innerHTML=`<div class="row"><strong>A little better every day</strong><span style="font-size:10px">${percent()}%</span></div><div class="progress-track"><span style="width:${percent()}%"></span></div><div class="muted" style="font-size:10px">${progress.mastered.length} of ${topics.length} lessons completed</div>`}}else{s.selected=null};$('#quiz').innerHTML=quizMarkup(t)};if(e.target.closest('#retryQuiz')){quizState[t.id]={index:0,selected:null,passed:[]};$('#quiz').innerHTML=quizMarkup(t)}}}
function labInfo(t){const info={array:['Indexed array lab','Explore the list operations behind this idea.'],linked:['Linked-chain intuition lab','Follow a chain one node at a time.'],stack:['LIFO stack lab','Watch the most recently added item leave first.'],queue:['FIFO queue lab','Watch arrivals leave in their original order.'],hash:['Hash-bucket intuition lab','Numeric keys go into bucket key mod 4; collisions share a bucket.'],tree:['BST search lab','Explore ordered branching. For balanced-tree lessons, this is the search intuition, not a balancing simulation.'],heap:['Min-heap priority lab','Remove the smallest item, then inspect the repaired heap.'],trie:['Shared-prefix lab','Find the shared beginnings of CAT, CAR, CART, and DOG.'],range:['Static range-sum lab','Watch two prefix totals give an interval sum. This is the range-query intuition, not a segment/Fenwick implementation.'],graph:['Graph exploration lab','Explore connections; the buttons run BFS and DFS on this undirected example.'],bfs:['Breadth-first traversal lab','Explore this graph in distance layers.'],dfs:['Depth-first traversal lab','Explore one branch, then backtrack.'],weighted:['Dijkstra intuition lab','These nonnegative edges demonstrate shortest-path relaxation. Other graph lessons use this as a related lab, not as their own algorithm simulation.'],search:['Linear search lab','Find the value 8 by checking one item at a time.'],binary:['Binary search lab','Find 8 in a sorted array by discarding halves.'],sort:[t.title+' lab','Step through this sorting algorithm on a small input.'],merge:['Merge-sort lab','Watch sorted subranges grow as halves are merged.'],quick:['Quick-sort partition lab','Watch an in-place pivot partition and its recursive subranges.'],recursion:['Recursive factorial lab','Watch calls get smaller, then return their answers.'],backtrack:['Permutation backtracking lab','Watch choose, explore, and undo on three items.'],greedy:['Greedy interval lab','Pick compatible activities by earliest finish time.'],dp:['Fibonacci DP intuition lab','Reuse the previous two answers. Other DP lessons use this as a related state-reuse lab, not their specific recurrence.'],pointers:['Two-pointer pair-sum lab','Find a pair summing to 10 in a sorted array.'],window:['Fixed-size sliding-window lab','Slide a three-item frame and update its sum.'],bits:['Bit-mask lab','Toggle switches and watch the represented integer change.'],bigo:['Growth comparison lab','Change n to compare the number of basic operations.'],matrix:['Grid-coordinate lab','Visit a cell by its row and column.']};let a=info[t.sim]||info.array;return{title:a[0],note:a[1]}}
function labMarkup(t){const info=labInfo(t);return `<div class="lab"><div class="lab-head"><strong>${info.title}</strong><span>INTERACTIVE · NO CODE NEEDED</span></div><div class="lab-scene" id="labScene"></div><div class="lab-controls" id="labControls"></div><p class="lab-message" id="labMessage" role="status" aria-live="polite"></p></div>`}
function resetLab(t){clearInterval(timer);timer=null;labState={a:['search','array','linked','stack','queue'].includes(t.sim)?[4,8,12,6]:['binary','pointers','range','window'].includes(t.sim)?[2,4,6,8,10,12]:[7,3,9,2,6],step:0,active:-1,done:[],mode:t.sim==='dfs'?'dfs':'bfs',bits:0,n:8,word:'CAT',message:'Try an action below. Every change has a reason.'};if(t.sim==='heap')labState.a=[2,3,9,7,6];if(['sort','merge','quick'].includes(t.sim))labState.frames=sortFrames(t.id,labState.a);paintLab(t)}
function boxes(a,active=[],done=[],linked=false){return `<div class="blocks">${a.map((v,i)=>`${linked&&i?'<span class="connector">→</span>':''}<div class="block-wrap"><div class="block ${active.includes(i)?'active':''} ${done.includes(i)?'done':''}">${esc(v)}</div><div class="index">${linked?'node '+(i+1):'['+i+']'}</div></div>`).join('')}${linked?'<span class="connector">→ ∅</span>':''}</div>`}
function graphSVG(mode,active,done,weighted=false){let pos=[[40,88],[145,35],[145,145],[260,35],[260,145],[375,88]],edges=[[0,1,2],[0,2,5],[1,3,1],[1,4,4],[2,5,2],[3,4,2],[4,5,1]];return `<svg class="graph-svg" role="img" aria-label="Six vertices A to F connected by edges${weighted?' with nonnegative weights':''}" viewBox="0 0 415 180">${edges.map(([u,v,w])=>`<line x1="${pos[u][0]}" y1="${pos[u][1]}" x2="${pos[v][0]}" y2="${pos[v][1]}" stroke="#bccdb0" stroke-width="2"/>${weighted?`<text x="${(pos[u][0]+pos[v][0])/2+6}" y="${(pos[u][1]+pos[v][1])/2-6}">${w}</text>`:''}`).join('')}${pos.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="18" stroke="${i===active?'#d69862':'#94af7a'}" stroke-width="1.5" fill="${i===active?'#f3d4ae':done.includes(i)?'#d5e99e':'#fffef9'}"/><text x="${x}" y="${y+5}" text-anchor="middle">${String.fromCharCode(65+i)}</text>`).join('')}</svg>`}
function treeSVG(a,active=-1,heap=false){let p=[[200,22],[110,72],[290,72],[65,125],[150,125],[250,125],[335,125]];return `<svg class="tree-svg" role="img" aria-label="${heap?'Min heap':'Binary search tree'} with values ${a.join(', ')}" viewBox="0 0 400 150">${a.slice(1).map((v,j)=>{let i=j+1,par=Math.floor((i-1)/2);return `<line x1="${p[par][0]}" y1="${p[par][1]}" x2="${p[i][0]}" y2="${p[i][1]}" stroke="#aac19a" stroke-width="2"/>`}).join('')}${a.map((v,i)=>`<circle cx="${p[i][0]}" cy="${p[i][1]}" r="17" fill="${active===i?'#f0d3ac':'#e3efce'}" stroke="#91ad71"/><text x="${p[i][0]}" y="${p[i][1]+4}" text-anchor="middle">${v}</text>`).join('')}</svg>`}
function sortFrames(id,input){let a=[...input],f=[{a:[...a],active:[],message:'An unsorted row. Step once to start.'}];const record=(active,message)=>f.push({a:[...a],active,message});if(id==='selection'){for(let i=0;i<a.length;i++){let m=i;for(let j=i+1;j<a.length;j++)if(a[j]<a[m])m=j;[a[i],a[m]]=[a[m],a[i]];record([i,m],`Minimum ${a[i]} takes position ${i}.`)}}else if(id==='insertion'){for(let i=1;i<a.length;i++){let x=a[i],j=i-1;while(j>=0&&a[j]>x){a[j+1]=a[j];j--}a[j+1]=x;record([j+1],`Insert ${x} into the sorted prefix.`)}}else if(id==='merge'||id==='divide'){const rec=(l,r)=>{if(r-l<2)return;let m=Math.floor((l+r)/2);rec(l,m);rec(m,r);let b=a.slice(l,m),c=a.slice(m,r),out=[],i=0,j=0;while(i<b.length&&j<c.length)out.push(b[i]<=c[j]?b[i++]:c[j++]);out.push(...b.slice(i),...c.slice(j));a.splice(l,r-l,...out);record(Array.from({length:r-l},(_,i)=>l+i),`Merge sorted ranges [${l},${m}) and [${m},${r}).`)};rec(0,a.length)}else if(id==='quick'){const rec=(l,r)=>{if(l>=r)return;let p=a[r],i=l;for(let j=l;j<r;j++){if(a[j]<=p){[a[i],a[j]]=[a[j],a[i]];i++}}[a[i],a[r]]=[a[r],a[i]];record([i],`Pivot ${p} reaches index ${i}; smaller keys left, larger right.`);rec(l,i-1);rec(i+1,r)};rec(0,a.length-1)}else if(id==='counting'){let c=Array(10).fill(0);for(let x of a)c[x]++;record([],`Counts: ${c.map((n,i)=>n?i+' occurs '+n:'').filter(Boolean).join(', ')}.`);a=c.flatMap((n,i)=>Array(n).fill(i));record(a.map((_,i)=>i),'Reconstruct values from the counts.')}else if(id==='radix'){a=[17,3,29,12,6];f[0].a=[...a];for(let place of [1,10]){let buckets=Array.from({length:10},()=>[]);for(let x of a)buckets[Math.floor(x/place)%10].push(x);a=buckets.flat();record(a.map((_,i)=>i),`Stable pass on the ${place===1?'ones':'tens'} digit.`)}}else if(id==='bucket'){a=[.7,.3,.9,.2,.6];f[0].a=[...a];let b=Array.from({length:5},()=>[]);for(let x of a)b[Math.floor(x*5)].push(x);record([],`Buckets: ${b.map(x=>'['+x.join(', ')+']').join(' ')}`);a=b.flatMap(x=>x.sort((a,b)=>a-b));record(a.map((_,i)=>i),'Sort each bucket, then concatenate in bucket order.')}else{for(let end=a.length-1;end>0;end--)for(let i=0;i<end;i++){let swap=a[i]>a[i+1];if(swap)[a[i],a[i+1]]=[a[i+1],a[i]];record([i,i+1],swap?'Out-of-order neighbors swap.':'These neighbors already have the right order.')}}f.push({a:[...a],active:[],message:'Sorted! Each value is no larger than the next.'});return f}
function paintLab(t){let s=labState,sim=t.sim,scene='',controls='';const btn=(id,txt,primary=false)=>`<button class="btn ${primary?'primary':''}" data-lab="${id}">${txt}</button>`;const valueInput=`<label>Value <input id="labValue" type="number" value="5" min="-99" max="99" aria-label="Value for the experiment"></label>`;if(['array','linked','stack','queue','hash','heap'].includes(sim)){if(sim==='stack'){scene=`<div class="blocks stack-blocks">${s.a.map((v,i)=>`<div class="block-wrap"><div class="block ${i===s.active?'active':''}">${v}${i===s.a.length-1?' <small> ← top</small>':''}</div></div>`).join('')}</div><div class="lab-caption">Bottom → top · Last in, first out</div>`}else if(sim==='heap')scene=treeSVG(s.a,s.active,true)+`<div class="lab-caption">Parent ≤ children · minimum at the root</div>`;else if(sim==='hash'){let b=Array.from({length:4},()=>[]);s.a.forEach(x=>b[((x%4)+4)%4].push(x));scene=`<div class="blocks">${b.map((v,i)=>`<div class="block-wrap"><div class="block" style="min-width:75px;height:auto;min-height:50px;padding:8px;font-size:12px">${v.join(' → ')||'empty'}</div><div class="index">bucket ${i}</div></div>`).join('')}</div><div class="lab-caption">hash(key) = key mod 4 · collision chains keep distinct keys</div>`}else scene=boxes(s.a,[s.active],[],sim==='linked')+`<div class="lab-caption">${sim==='queue'?'Front ← departures · arrivals → rear':sim==='linked'?'Head → next → next → end':'Each slot has an index. The first index is 0.'}</div>`;controls=valueInput+btn('add',sim==='stack'?'Push ↑':sim==='queue'?'Enqueue →':sim==='heap'?'Insert priority':sim==='hash'?'Insert key':'Append +',true)+btn('remove',sim==='stack'?'Pop ↓':sim==='queue'?'Dequeue ←':sim==='heap'?'Extract minimum':'Remove last')+(sim==='array'?btn('insert','Insert at index 1'):sim==='linked'?btn('follow','Follow next →'):'')}else if(['sort','merge','quick'].includes(sim)){let f=s.frames[s.step];scene=boxes(f.a,f.active,s.step===s.frames.length-1?f.a.map((_,i)=>i):[])+`<div class="lab-caption">Frame ${s.step+1} / ${s.frames.length}</div>`;s.message=f.message;controls=btn('step','Next step →',true)+btn('play',timer?'Pause Ⅱ':'Animate ▷')}else if(['graph','bfs','dfs','weighted'].includes(sim)){let order=sim==='weighted'?[0,1,3,2,4,5]:s.mode==='dfs'?[0,1,3,4,5,2]:[0,1,2,3,4,5];let active=s.step?order[s.step-1]:-1,done=order.slice(0,Math.max(0,s.step-1));scene=graphSVG(s.mode,active,done,sim==='weighted')+`<div class="lab-caption">${sim==='weighted'?'Settled distances: ':s.mode.toUpperCase()+': '}${order.slice(0,s.step).map(i=>String.fromCharCode(65+i)+(sim==='weighted'?':'+[0,2,5,3,5,6][i]:'')).join(' → ')||'Start at A'}</div>`;controls=btn('step','Visit next →',true)+btn('play',timer?'Pause Ⅱ':'Animate ▷')+(sim==='graph'?btn('bfs','Use BFS')+btn('dfs','Use DFS'):'');if(s.step)s.message=sim==='weighted'?`Settle ${String.fromCharCode(65+active)} at distance ${[0,2,5,3,5,6][active]}. Nonnegative edges keep settled distances final.`:s.mode==='bfs'?'FIFO exploration reaches nearby vertices before farther layers.':'Follow the current branch until no unseen neighbor remains, then backtrack.'}else if(sim==='tree'){let a=[8,4,12,2,6,10,14];scene=treeSVG(a,s.active)+`<div class="lab-caption">Left keys are smaller. Right keys are larger.</div>`;controls=valueInput+btn('find','Search the tree',true)}else if(['search','binary','pointers'].includes(sim)){let active=sim==='pointers'?[0,5-s.step]:s.active<0?[]:[s.active];scene=boxes(s.a,active,s.done)+`<div class="lab-caption">${sim==='pointers'?'Target sum: 10':sim==='binary'?'Sorted input · target: 8':'Unsorted input · target: 8'}</div>`;controls=btn('step',sim==='pointers'?'Move pointers →':'Inspect next →',true)}else if(['range','window'].includes(sim)){let start=s.step%(s.a.length-2),end=start+3,sum=s.a.slice(start,end).reduce((a,b)=>a+b,0),p=[0];s.a.forEach(x=>p.push(p.at(-1)+x));scene=boxes(s.a,Array.from({length:3},(_,i)=>start+i))+`<div class="lab-caption">Window [${start},${end}) · sum = ${sum}${sim==='range'?`<br>prefix[${end}] − prefix[${start}] = ${p[end]} − ${p[start]} = ${sum}`:''}</div>`;controls=btn('step',sim==='window'?'Slide the frame →':'Next range →',true);s.message=sim==='range'?'Subtract the total before the range from the total at its end.':'The frame covers exactly three consecutive items.'}else if(sim==='bits'){scene=`<div class="blocks">${[7,6,5,4,3,2,1,0].map(i=>`<div class="block-wrap"><button class="block bit ${(s.bits>>i)&1?'done':''}" data-bit="${i}" aria-label="Toggle bit ${i}" aria-pressed="${!!((s.bits>>i)&1)}">${(s.bits>>i)&1}</button><div class="index">2⁽${i}⁾</div></div>`).join('')}</div><div class="lab-caption">Binary ${s.bits.toString(2).padStart(8,'0')} = decimal <strong>${s.bits}</strong></div>`;controls=btn('toggle','Toggle bit 2 (XOR 4)',true);s.message='Click any switch. A set bit contributes its power of two to the total.'}else if(sim==='bigo'){let ns=[1,Math.ceil(Math.log2(s.n)),s.n,s.n*s.n],max=Math.max(...ns);scene=`<div class="speed-count">${ns.map((n,i)=>`<div class="bar" style="height:${Math.max(8,n/max*110)}px;background:${colors[i%colors.length][1]}"><span>${n}</span><label>${['1','⌈log₂ n⌉','n','n²'][i]}</label></div>`).join('')}</div><div class="lab-caption" style="margin-top:39px">n = ${s.n} · representative operation counts</div>`;controls=`<label>Input size n <input id="growthN" type="number" min="2" max="64" value="${s.n}"></label>`+btn('growth','Compare growth',true);s.message='These are exact values of example growth functions, not measured runtimes.'}else if(sim==='matrix'){let r=Math.floor(s.step/3)%3,c=s.step%3;scene=`<div style="display:grid;grid-template-columns:repeat(3,45px);gap:9px">${Array.from({length:9},(_,i)=>`<div class="block ${i===s.step%9?'active':''}">${i+1}</div>`).join('')}</div><div class="lab-caption">grid[${r}][${c}] = ${s.step%9+1}</div>`;controls=btn('step','Visit next cell →',true)}else if(sim==='dp'){let vals=[0,1,1,2,3,5,8,13];scene=boxes(vals.slice(0,s.step+2),s.step>0?[s.step,s.step+1]:[0,1])+`<div class="lab-caption">F(i) = F(i−1) + F(i−2) · store answers once</div>`;controls=btn('step','Fill the next state →',true);s.message=s.step?`F(${s.step+1}) = ${vals[s.step-1]} + ${vals[s.step]} = ${vals[s.step+1]}.`:'Base cases: F(0)=0 and F(1)=1.'}else if(sim==='recursion'){let frames=[['factorial(4)','Need 4 × factorial(3).'],['factorial(3)','Need 3 × factorial(2).'],['factorial(2)','Need 2 × factorial(1).'],['factorial(1)','Base case! Return 1.'],['2 × 1 = 2','Return 2 to factorial(3).'],['3 × 2 = 6','Return 6 to factorial(4).'],['4 × 6 = 24','All calls complete: factorial(4) = 24.']];scene=`<div class="blocks"><div class="block active" style="min-width:190px">${frames[s.step][0]}</div></div><div class="lab-caption">${s.step<4?'Call depth: '+(s.step+1):'Returning answers up the call stack'}</div>`;s.message=frames[s.step][1];controls=btn('step','Next call / return →',true)}else if(sim==='backtrack'){let paths=[[],[1],[1,2],[1,2,3],[1,2],[1],[1,3],[1,3,2],[1,3],[1],[],[2],[2,1],[2,1,3]];scene=boxes(paths[s.step],[],paths[s.step].length===3?[0,1,2]:[])+`<div class="lab-caption">${paths[s.step].length===3?'A complete permutation! Copy it before undoing.':paths[s.step].length?'Current partial choice':'Empty choice: ready to explore'}</div>`;controls=btn('step','Choose / undo →',true);s.message=s.step&&paths[s.step].length<paths[s.step-1].length?'Undo a choice so the next branch starts cleanly.':'Choose another unused number and explore.'}else if(sim==='greedy'){let intervals=['[1,3]','[2,5]','[3,6]','[5,8]','[6,9]'],accepted=[0,2,4],done=accepted.filter(i=>i<s.step);scene=boxes(intervals,s.step<5?[s.step]:[],done)+`<div class="lab-caption">Sorted by finish time · intervals may touch at endpoints</div>`;controls=btn('step','Consider activity →',true);s.message=s.step?accepted.includes(s.step-1)?'Accept this activity: it begins at or after the last chosen finish.':'Skip this activity: it overlaps the previous chosen activity.':'Choose the compatible activity that finishes first.'}else if(sim==='trie'){let words=['CAT','CAR','CART','DOG'],word=words[s.step%4],letters=word.split('');scene=`${boxes(letters,[],letters.map((_,i)=>i),true)}<div class="lab-caption">${word} → terminal ✓<br>CAT, CAR, CART share C → A; CAR is a word and also a prefix of CART.</div>`;controls=btn('step','Explore next word →',true);s.message='A terminal marker means “whole word.” Shared character paths mean “common prefix.”'};$('#labScene').innerHTML=scene;$('#labControls').innerHTML=controls+btn('reset','↺ Reset');$('#labMessage').textContent=s.message;}
function labFinished(t){let s=labState;return ['sort','merge','quick'].includes(t.sim)?s.step>=s.frames.length-1:['graph','bfs','dfs','weighted'].includes(t.sim)?s.step>=6:false}
function stepLab(t){let s=labState;switch(t.sim){case 'sort':case 'merge':case 'quick':s.step=Math.min(s.step+1,s.frames.length-1);break;case 'graph':case 'bfs':case 'dfs':case 'weighted':s.step=Math.min(s.step+1,6);break;case 'binary':{let positions=[2,4,3];s.active=positions[Math.min(s.step,2)];s.message=['Middle is 6, below 8. Discard indexes 0–2.','Middle of indexes 3–5 is 10. Discard indexes 4–5.','Index 3 contains 8. Found in three checks!'][Math.min(s.step,2)];s.step=Math.min(s.step+1,3);break}case 'search':s.active=Math.min(s.step,1);s.message=s.step?'8 found at index 1 after two comparisons.':'Index 0 is 4, not 8. Advance one slot.';s.step=Math.min(s.step+1,2);break;case 'pointers':s.step=Math.min(s.step+1,2);s.message=['','2 + 10 = 12 is too large. Move the right pointer left.','2 + 8 = 10. Found!'][s.step];break;case 'dp':s.step=Math.min(s.step+1,6);break;case 'recursion':s.step=Math.min(s.step+1,6);break;case 'backtrack':s.step=(s.step+1)%14;break;case 'greedy':s.step=Math.min(s.step+1,5);break;default:s.step++};if(labFinished(t)&&timer){clearInterval(timer);timer=null}paintLab(t)}
function bindLab(t){resetLab(t);$('.lab').onclick=e=>{let bit=e.target.closest('[data-bit]');if(bit){labState.bits^=1<<+bit.dataset.bit;paintLab(t);return}let b=e.target.closest('[data-lab]');if(!b)return;let action=b.dataset.lab,s=labState;if(action==='reset'){resetLab(t);return};if(action==='step'){stepLab(t);return};if(action==='play'){if(timer){clearInterval(timer);timer=null;paintLab(t)}else{if(labFinished(t))resetLab(t);timer=setInterval(()=>stepLab(t),900);paintLab(t)}return};if(action==='bfs'||action==='dfs'){s.mode=action;s.step=0;paintLab(t);return};if(action==='toggle'){s.bits^=4;paintLab(t);return};if(action==='growth'){let n=Number($('#growthN').value);if(!Number.isInteger(n)||n<2||n>64){toast('Choose a whole input size from 2 to 64.');return}s.n=n;paintLab(t);return}let x=Number($('#labValue')?.value);if(['add','insert','find'].includes(action)&&(!Number.isFinite(x)||!Number.isInteger(x)||x<-99||x>99)){toast('Choose a whole number between −99 and 99.');return};if(action==='add'){if(s.a.length>=7){toast('This small lab holds seven items. Remove one to make room.');return};if(t.sim==='hash'&&s.a.includes(x)){s.message='This key is already stored. A map updates its value instead of adding a duplicate key.'}else{s.a.push(x);s.active=s.a.length-1;s.message=`Added ${x}${t.sim==='queue'?' at the rear':t.sim==='stack'?' on top':t.sim==='hash'?` to bucket ${((x%4)+4)%4}`:' at the end'}.`;if(t.sim==='heap'){let i=s.a.length-1;while(i>0){let p=Math.floor((i-1)/2);if(s.a[p]<=s.a[i])break;[s.a[p],s.a[i]]=[s.a[i],s.a[p]];i=p}s.active=i;s.message=`Insert ${x}, then bubble up until the parent is no larger.`}}};if(action==='remove'){if(!s.a.length){s.message='Nothing to remove: the structure is empty.'}else{let v;if(t.sim==='queue')v=s.a.shift();else if(t.sim==='heap'){v=s.a[0];let last=s.a.pop();if(s.a.length){s.a[0]=last;let i=0;while(2*i+1<s.a.length){let j=2*i+1;if(j+1<s.a.length&&s.a[j+1]<s.a[j])j++;if(s.a[i]<=s.a[j])break;[s.a[i],s.a[j]]=[s.a[j],s.a[i]];i=j}}s.active=0}else v=s.a.pop();s.message=`Removed ${v}${t.sim==='queue'?' from the front':t.sim==='stack'?' from the top':t.sim==='heap'?' (the minimum); the heap was repaired':''}.`;s.active=-1}};if(action==='insert'){if(s.a.length>=7){toast('Remove one item first.');return}s.a.splice(1,0,x);s.active=1;s.message=`Insert ${x} at index 1. Later items shift right: this can take O(n).`};if(action==='follow'){s.active++;if(s.active>=s.a.length){s.active=-1;s.message='Reached None. Begin again at the head.'}else s.message=`Following links: node ${s.active+1} stores ${s.a[s.active]}.`};if(action==='find'){let a=[8,4,12,2,6,10,14],i=0,path=[];while(i<a.length){path.push(a[i]);if(a[i]===x)break;i=x<a[i]?2*i+1:2*i+2}s.active=i<a.length?i:-1;s.message=`Path: ${path.join(' → ')}. ${i<a.length?'Found '+x+'!':'Missing child: '+x+' is not stored.'}`}paintLab(t)};}
function playground(id){let t=topics.find(t=>t.id===id)||topics.find(t=>t.id==='arrays');currentTopic=t;return `<div class="page-intro"><span class="eyebrow">Curiosity gets its own playground</span><h1>Touch an idea.<br>Watch it make sense.</h1><p>Change a value. Follow a link. Step through an algorithm. The best way to understand a thing is to play with it.</p></div><label class="muted" for="labPicker">Choose a topic</label><select id="labPicker" class="lab-picker">${chapterInfo.map((c,i)=>`<optgroup label="${c[0]}">${topics.filter(x=>x.chapter===i).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.title}</option>`).join('')}</optgroup>`).join('')}</select><div class="section-head"><div><h2>${labInfo(t).title}</h2><p>${labInfo(t).note}</p></div><a class="text-link" href="#lesson/${t.id}">Read the full story →</a></div>${labMarkup(t)}<div class="bottom-banner"><div><strong>Why it works</strong><p>${t.meaning}</p></div></div>`}
function journey(){let badges=[['🌱','First little step',1,'Complete one lesson'],['✧','Finding your rhythm',5,'Complete five lessons'],['♧','Growing branches',15,'Complete 15 lessons'],['⚡','Problem solver',35,'Complete 35 lessons'],['✦','A world understood',topics.length,'Complete every lesson']];return `<div class="page-intro"><span class="eyebrow">Every idea counts</span><h1>Look how far your<br>curiosity can take you.</h1><p>Progress is about understanding, not racing. Your notes, bookmarks, and completed checks live here in this browser.</p></div><div class="stats"><div class="stat"><b>${progress.mastered.length}<span>of ${topics.length} lessons completed</span></b></div><div class="stat"><b>${xp()}<span>XP from understood ideas</span></b></div><div class="stat"><b>${progress.visited.length}<span>lessons explored</span></b></div></div><div class="badge-grid">${badges.map(([symbol,title,n,desc])=>`<div class="badge ${progress.mastered.length<n?'locked':''}"><div class="badge-symbol">${symbol}</div><strong>${title}</strong><span class="muted" style="font-size:10px">${progress.mastered.length>=n?'✓ Earned':desc}</span></div>`).join('')}</div><div class="section-head"><div><h2>Your saved discoveries</h2><p>A shortcut back to the ideas you want to revisit.</p></div></div><div class="lesson-list">${progress.bookmarks.length?topics.filter(t=>progress.bookmarks.includes(t.id)).map(t=>item(t,topics.indexOf(t))).join(''):'<p class="muted">Open any lesson and choose ☆ Save lesson to keep it here.</p>'}</div><div class="section-head"><div><h2>Ideas you’ve made your own</h2><p>Completed lessons are always open for revision.</p></div><button class="text-link" id="exportProgress">Export progress ↓</button></div><div class="lesson-list">${topics.filter(t=>progress.mastered.includes(t.id)).map(t=>item(t,topics.indexOf(t))).join('')||'<p class="muted">Your first small win is waiting. <a class="text-link" href="#lesson/foundations">Start with a story →</a></p>'}</div>${progress.mastered.length===topics.length?'<div class="certificate"><span class="eyebrow">A complete world of ideas.</span><h2>You completed Odoo Functional fieldnotes ✦</h2><p>Keep practicing: mastery grows when you solve new problems.</p><button class="btn" id="printJourney">Print your journey</button></div>':''}<div class="source-note">Browser data can be cleared by your browser. Export a copy to keep your notes and progress.</div>`}
function cheatsheet(){return `<div class="page-intro"><span class="eyebrow">A little less to remember</span><h1>Your DSA revision sheet.</h1><p>Key ideas and tradeoffs in one place. Follow a topic link whenever you want the full story.</p><button class="btn" id="printSheet">Print / save as PDF ↗</button></div><label for="sheetFilter" class="visually-hidden">Filter revision sheet</label><input id="sheetFilter" class="filter-input" placeholder="Filter by topic, complexity, or use case…"><div class="table-wrap"><table><thead><tr><th>Idea</th><th>Time & memory</th><th>Use it for</th></tr></thead><tbody id="sheetRows">${topics.map(t=>`<tr><td><a href="#lesson/${t.id}">${t.title} ↗</a></td><td>${t.cost}</td><td>${t.use}</td></tr>`).join('')}</tbody></table></div><p class="source-note">A broad engineering DSA curriculum, with original explanations. For deeper lectures and exercises, explore <a href="https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/" target="_blank" rel="noopener">MIT Introduction to Algorithms</a> and <a href="https://algs4.cs.princeton.edu/home/" target="_blank" rel="noopener">Princeton Algorithms</a>. Complexity depends on implementation and stated assumptions.</p>`}
function route(){clearInterval(timer);timer=null;let [view='home',id]=location.hash.slice(1).split('/');if(!['home','course','lesson','playground','journey','cheatsheet'].includes(view))view='home';currentTopic=null;let content;if(view==='lesson'){let t=topics.find(t=>t.id===id);if(!t){location.hash='course';return}currentTopic=t;if(!progress.visited.includes(t.id))progress.visited.push(t.id);progress.last=t.id;save();content=lesson(t)}else if(view==='playground')content=playground(id);else content=({home,course,journey,cheatsheet})[view]();$('#app').innerHTML=layout(content,view);document.title=(currentTopic?currentTopic.title:({home:'Big ideas. Little steps.',course:'Learning path',journey:'My journey',cheatsheet:'Revision sheet'})[view])+' — Odoo Functional fieldnotes';window.scrollTo(0,0);bindCommon();if(view==='lesson')bindLesson(currentTopic);if(view==='playground'){bindLab(currentTopic);$('#labPicker').onchange=e=>location.hash='playground/'+e.target.value};if(view==='course'){if(id!==undefined&&$('#chapter-'+id))requestAnimationFrame(()=>$('#chapter-'+id).scrollIntoView());$('#courseFilter').oninput=e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.chapter-section').forEach(sec=>{sec.querySelectorAll('.lesson-item').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q));sec.hidden=![...sec.querySelectorAll('.lesson-item')].some(el=>!el.hidden)})}};if(view==='cheatsheet'){$('#sheetFilter').oninput=e=>document.querySelectorAll('#sheetRows tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$('#printSheet').onclick=()=>window.print()};if(view==='journey'){$('#exportProgress').onclick=()=>{let blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='odoo-learning-progress.json';a.click();URL.revokeObjectURL(url);toast('Your learning journey has been exported.')};if($('#printJourney'))$('#printJourney').onclick=()=>window.print()}}
function bindCommon(){const openMenu=()=>{$('#sidebar').classList.toggle('open');$('#menuScrim').classList.toggle('open');$('#menuButton').setAttribute('aria-expanded',$('#sidebar').classList.contains('open'))};$('#menuButton').onclick=openMenu;$('#menuScrim').onclick=openMenu;$('#openSearch').onclick=openSearch}
function bindLesson(t){bindLab(t);bindQuiz(t);let walk=0;$('#walkStep').onclick=()=>{let s=t.steps[walk%3];$('#walkText').textContent='Step '+((walk%3)+1)+': '+s;walk++};$('#bookmark').onclick=()=>{if(progress.bookmarks.includes(t.id))progress.bookmarks=progress.bookmarks.filter(id=>id!==t.id);else progress.bookmarks.push(t.id);save();$('#bookmark').textContent=progress.bookmarks.includes(t.id)?'★ Saved':'☆ Save lesson';toast(progress.bookmarks.includes(t.id)?'Saved to your journey.':'Bookmark removed.')};$('#copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(t.code);toast('Functional checklist copied.')}catch{toast('Select the example text to copy it in this browser.')}};$('#notes').oninput=e=>{progress.notes[t.id]=e.target.value;save();$('#noteStatus').textContent=storageAvailable?'✓ Your “aha!” is saved.':'Saved for this session.'};document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.scroll).scrollIntoView({behavior:'smooth'})});if($('#focusToggle'))$('#focusToggle').onclick=()=>{document.body.classList.toggle('focus-mode');toast('Focus view on. Press F to toggle it.')}}
function openSearch(){$('#searchDialog').showModal();$('#searchInput').value='';searchResults('');$('#searchInput').focus()}
function searchResults(q){let found=topics.filter(t=>(t.title+' '+t.analogy+' '+t.meaning+' '+t.use).toLowerCase().includes(q.toLowerCase()));$('#searchResults').innerHTML=found.slice(0,25).map(t=>`<a class="search-result" href="#lesson/${t.id}">${t.title}<small>${chapterInfo[t.chapter][0]} · ${t.analogy}</small></a>`).join('')||'<p class="muted">No matching ideas yet. Try a broader word.</p>';$('#searchResults').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#searchDialog').close())}
$('#closeSearch').onclick=()=>$('#searchDialog').close();$('#searchInput').oninput=e=>searchResults(e.target.value);$('#searchDialog').onclick=e=>{if(e.target===$('#searchDialog')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#searchDialog').open)openSearch()};if(e.key.toLowerCase()==='f'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#searchDialog').open&&location.hash.startsWith('#lesson')){document.body.classList.toggle('focus-mode');toast(document.body.classList.contains('focus-mode')?'Focus view on. Press F to return.':'Full lesson view restored.')}});// Notebook owns routing.
